public sealed class PaymentMetrics
{
    private readonly Counter<long> _created;
    private readonly Histogram<double> _authLatency;
    private readonly UpDownCounter<long> _inFlight;

    public PaymentMetrics(IMeterFactory factory)
    {
        var meter = factory.Create("Bank.Payments");
        _created = meter.CreateCounter<long>("payments.created", unit: "{payment}", description: "Payments created");
        _authLatency = meter.CreateHistogram<double>("payments.authorisation.duration", unit: "s",
            advice: new InstrumentAdvice<double> { HistogramBucketBoundaries = [0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5] });
        _inFlight = meter.CreateUpDownCounter<long>("payments.in_flight", unit: "{payment}");
        meter.CreateObservableGauge("payments.outbox.oldest_age", () => OutboxProbe.OldestAgeSeconds(), unit: "s");
    }

    public void Created(string scheme, string channel) => _created.Add(1, new("scheme", scheme), new("channel", channel));
    public void AuthorisationTook(TimeSpan d, string outcome) => _authLatency.Record(d.TotalSeconds, new KeyValuePair<string, object?>("outcome", outcome));
    public IDisposable Track() { _inFlight.Add(1); return new Releaser(() => _inFlight.Add(-1)); }
}
