static readonly ActivitySource Source = new("Bank.Ledger.Consumer");
static readonly TextMapPropagator Propagator = Propagators.DefaultTextMapPropagator;
static readonly Histogram<double> QueueLatency = new Meter("Bank.Ledger").CreateHistogram<double>("messaging.queue.latency", "s");

// Producer side (or outbox relay): inject context into headers
Propagator.Inject(new PropagationContext(Activity.Current!.Context, Baggage.Current), headers,
    (h, key, value) => h.Add(key, Encoding.UTF8.GetBytes(value)));
headers.Add("produced-at", Encoding.UTF8.GetBytes(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString()));

// Consumer side: extract and continue the trace
var parent = Propagator.Extract(default, msg.Message.Headers,
    (h, key) => h.TryGetLastBytes(key, out var b) ? [Encoding.UTF8.GetString(b)] : []);
using var span = Source.StartActivity("payments.settled process", ActivityKind.Consumer, parent.ActivityContext);
span?.SetTag("messaging.system", "kafka"); span?.SetTag("messaging.destination.name", msg.Topic);
var producedAt = DateTimeOffset.FromUnixTimeMilliseconds(long.Parse(Encoding.UTF8.GetString(msg.Message.Headers.GetLastBytes("produced-at"))));
