public sealed class SettlementJob(IMeterFactory meters, ILogger<SettlementJob> log)
{
    private readonly Meter _m = meters.Create("Bank.Settlement");
    public async Task RunAsync(DateOnly businessDate, CancellationToken ct)
    {
        using var run = Source.StartActivity("settlement.run");
        run?.SetTag("settlement.business_date", businessDate.ToString("O"));
        var expected = await scheme.ExpectedCountAsync(businessDate, ct);
        var processed = 0; decimal total = 0;

        await foreach (var batch in reader.ReadBatchesAsync(businessDate, ct))
        {
            using var stage = Source.StartActivity("settlement.batch");
            (processed, total) = (processed + batch.Count, total + batch.Sum(x => x.Amount));
        }

        var ok = processed == expected && total == await scheme.ExpectedTotalAsync(businessDate, ct);   // completeness + correctness
        _m.CreateCounter<long>("settlement.records").Add(processed);
        await heartbeat.ReportAsync("settlement", businessDate, ok ? "success" : "reconciliation_failed", ct);   // dead-man's switch input
        if (!ok) log.LogError("Settlement {Date} mismatch: {Processed}/{Expected} records", businessDate, processed, expected);
    }
}
