// Shadow comparison for read operations: legacy authoritative, new service mirrored and compared
static readonly Counter<long> Compared = new Meter("Bank.Migration").CreateCounter<long>("migration.shadow.compared");

public async Task<AccountView> GetAccountAsync(string id, CancellationToken ct)
{
    var legacyTask = legacy.GetAccountAsync(id, ct);
    var shadowTask = Task.Run(() => modern.GetAccountAsync(id, CancellationToken.None));   // never affects the response

    var result = await legacyTask;
    _ = shadowTask.ContinueWith(t =>
    {
        var outcome = t.IsCompletedSuccessfully
            ? (Normalise(t.Result) == Normalise(result) ? "match" : "mismatch")
            : "shadow_error";
        Compared.Add(1, new("operation", "get_account"), new("outcome", outcome));
        if (outcome == "mismatch") log.LogWarning("Shadow mismatch for account {AccountRef}", Hash(id));   // no raw ids
    }, TaskScheduler.Default);
    return result;
}
